import{_ as n,o as r,c as a,ag as i}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Waschstraßen","description":"","frontmatter":{},"headers":[],"relativePath":"de/car-wash/tunnels.md","filePath":"de/car-wash/tunnels.md"}'),t={name:"de/car-wash/tunnels.md"};function s(l,e,d,h,o,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="waschstraßen" tabindex="-1">Waschstraßen <a class="header-anchor" href="#waschstraßen" aria-label="Permalink to &quot;Waschstraßen&quot;">​</a></h1><p>Eine Waschstraße besteht aus einer Einfahrt, an der der Fahrer anhält, einer Linie, der das Fahrzeug folgt, und den Bögen, Bürsten und dem Trockner entlang dieser Linie. Zwei Waschstraßen sind sofort einsatzbereit: <strong>Strawberry</strong> und <strong>Little Seoul</strong>.</p><h2 id="ablauf-einer-wasche" tabindex="-1">Ablauf einer Wäsche <a class="header-anchor" href="#ablauf-einer-wasche" aria-label="Permalink to &quot;Ablauf einer Wäsche&quot;">​</a></h2><ol><li>Der Fahrer hält an der Einfahrt, mit Blick zur Ausfahrt. Ein Hinweis zeigt den niedrigsten Preis.</li><li><strong>E</strong> öffnet das Waschmenü mit den Programmen und ihren Preisen (Job-Rabatte und Prozentsatz der Waschstraße inbegriffen).</li><li>Der Preis wird bezahlt, dann wird das Fahrzeug entlang der Linie geführt: Schaum, Bürsten, Spülen, Trockner, je nach Programm. Alle in der Nähe sehen dieselbe Wäsche.</li><li>An der Ausfahrt ist das Fahrzeug sauber, und gewachst, wenn das Programm Wachs enthält.</li></ol><p>Die Einfahrt lehnt die Wäsche ab, wenn:</p><ul><li>die Waschstraße bereits belegt ist (ein Fahrzeug nach dem anderen);</li><li>das Fahrzeug in die falsche Richtung zeigt;</li><li>ein anderes Fahrzeug die Spur blockiert;</li><li>die Fahrzeugklasse gesperrt oder das Fahrzeug zu breit ist (<code>BlockedClasses</code>, <code>MaxVehicleWidth</code>);</li><li>das Fahrzeug bereits sauber und <code>RequireDirt</code> an ist;</li><li>der Spieler nicht bezahlen kann.</li></ul><h2 id="der-editor-fur-waschstraßen" tabindex="-1">Der Editor für Waschstraßen <a class="header-anchor" href="#der-editor-fur-waschstraßen" aria-label="Permalink to &quot;Der Editor für Waschstraßen&quot;">​</a></h2><p>Öffne ihn mit <code>/nay:carwash</code> oder mit <strong>Waschstraßen verwalten</strong> auf der Seite Car Wash von <code>/nay</code>. Er braucht den Scope <code>nay_car_wash.config</code>.</p><p>Die Verwaltung listet die Waschstraßen auf: zu einer hingehen, sie bearbeiten, öffnen oder schließen, löschen. So fügst du eine hinzu:</p><ol><li><p><strong>Hier erstellen</strong>: Stell dich an die Einfahrt, mit Blick zur Ausfahrt. Oder übernimm eine der Waschanlagen des Basisspiels mit ihrer Schaltfläche <strong>… kopieren</strong>.</p></li><li><p>Wähle ein Element (Einfahrt, Linienanfang und Linienende, Bögen, Bürsten, Trockner) und verschiebe es mit den Schaltflächen oder der Tastatur:</p><ul><li>Pfeiltasten: vorwärts, zurück, links, rechts entlang der Spur;</li><li>Bild auf / Bild ab: Höhe;</li><li>Q / E: drehen;</li><li>Tab: nächstes Element.</li></ul><p>Drei Schrittweiten stehen für feine Anpassungen zur Verfügung.</p></li><li><p><strong>Zu meiner Position</strong> und <strong>Auf den Boden</strong> setzen das ausgewählte Element dorthin. <strong>Bewegen</strong> (G) gibt die Maus frei, damit du dich bewegen und umsehen kannst. Drücke erneut G, um das Panel zurückzuholen.</p></li><li><p><strong>Waschstraße speichern</strong>. Die Waschstraße ist sofort für jeden Spieler aktiv.</p></li></ol><p>Der Editor füllt die Einstellung <code>Tunnels</code>. Ihre Felder sind auf der Seite <a href="/de/car-wash/settings#waschstraßen">Einstellungen</a> beschrieben.</p>',11)])])}const f=n(t,[["render",s]]);export{g as __pageData,f as default};
